            <div id="markdown" class="tab-content">

                <div class="json-export" id="markdownExport"></div>

                <button class="btn-primary copy-btn" onclick="copyToClipboard('#markdownExport')">📋 Copy Markdown</button>

            </div>



            <div class="actions" style="margin-top: 20px;">

                <button class="btn-success" onclick="downloadPromptCard()">⬇️ Download as Text</button>

                <button class="btn-secondary" onclick="saveToLocalStorage()">💾 Save to Browser</button>

                <button class="btn-secondary" onclick="loadFromLocalStorage()">📂 Load from Browser</button>

                <button class="btn-danger" onclick="clearAll()">🗑️ Clear All</button>

            </div>

        </div>

