    <!-- Modal for viewing full patterns -->

    <div class="modal" id="modal">

        <div class="modal-content">

            <h3>Edit Pattern</h3>

            <textarea id="modalTextarea"></textarea>

            <div class="modal-actions">

                <button class="btn-primary" onclick="saveModalEdit()">Save</button>

                <button class="btn-secondary" onclick="closeModal()">Cancel</button>

            </div>

        </div>

    </div>



    <script>

        // Define prompt framing patterns

        const patterns = [

            {

                id: 1,

                name: "Direct & Clear",

                type: "Straightforward",

                template: "Task: {task}\n\nProvide a clear, concise response focused on the core requirement.",

                clarity: 95,

                flexibility: 60,

                creativity: 40,

                description: "Best for: Technical tasks, documentation, factual queries"

            },

            {

                id: 2,

                name: "Context-Rich",

                type: "Detailed",

                template: "Context: I need help with the following task.\n\nTask: {task}\n\nBackground: Consider relevant context, constraints, and best practices. Provide nuanced output that accounts for multiple perspectives.",

                clarity: 75,

                flexibility: 85,

                creativity: 70,

                description: "Best for: Complex problems, strategy, analysis"

            },

            {

                id: 3,

                name: "Persona & Role",

                type: "Roleplay",

                template: "You are an expert consultant specializing in this domain.\n\nClient request: {task}\n\nApproach this with your professional expertise, considering industry standards and innovative solutions.",

                clarity: 70,

                flexibility: 75,

                creativity: 90,

                description: "Best for: Creative work, specialized advice, brainstorming"

            }

        ];



        let selectedPattern = null;

        let currentEditingPatternId = null;



        // Initialize the workshop

        function init() {

            renderPatterns();

            setupEventListeners();

            updateStats();

        }



        function renderPatterns() {

            const grid = document.getElementById('patternsGrid');

            grid.innerHTML = '';



            patterns.forEach(pattern => {

                const card = document.createElement('div');

                card.className = `pattern-card pattern-${pattern.id}`;

                card.innerHTML = `

                    <span class="pattern-type">${pattern.type}</span>

                    <h3>${pattern.name}</h3>

                    <p style="font-size: 12px; color: #666; margin-bottom: 12px;">${pattern.description}</p>



                    <textarea id="template-${pattern.id}" data-pattern-id="${pattern.id}">${pattern.template}</textarea>



                    <div class="tradeoff-meter">

                        <div class="meter-label">

                            <span>Clarity</span>

                            <span id="clarity-${pattern.id}">${pattern.clarity}%</span>

                        </div>

                        <div class="meter-bar">

                            <div class="meter-fill" style="width: ${pattern.clarity}%"></div>

                        </div>

                    </div>



                    <div class="tradeoff-meter">

                        <div class="meter-label">

                            <span>Flexibility</span>

                            <span id="flexibility-${pattern.id}">${pattern.flexibility}%</span>

                        </div>

                        <div class="meter-bar">

                            <div class="meter-fill" style="width: ${pattern.flexibility}%"></div>

                        </div>

                    </div>



                    <div class="tradeoff-meter">

                        <div class="meter-label">

                            <span>Creativity</span>

                            <span id="creativity-${pattern.id}">${pattern.creativity}%</span>

                        </div>

                        <div class="meter-bar">

                            <div class="meter-fill" style="width: ${pattern.creativity}%"></div>

                        </div>

                    </div>



                    <div class="actions">

                        <button class="btn-primary" onclick="selectPattern(${pattern.id})">Use Pattern</button>

                        <button class="btn-secondary" onclick="editPattern(${pattern.id})">Edit</button>

                    </div>

                `;

                grid.appendChild(card);

            });

        }



        function selectPattern(patternId) {

            selectedPattern = patternId;

            const pattern = patterns.find(p => p.id === patternId);

            updateFinalPreview();

            document.querySelectorAll('.pattern-card').forEach(card => {

                card.style.opacity = '0.5';

            });

            document.querySelector(`.pattern-${patternId}`).style.opacity = '1';

        }



        function editPattern(patternId) {

            currentEditingPatternId = patternId;

            const textarea = document.getElementById(`template-${patternId}`);

            document.getElementById('modalTextarea').value = textarea.value;

            document.getElementById('modal').classList.add('active');

        }



        function saveModalEdit() {

            const newTemplate = document.getElementById('modalTextarea').value;

            const pattern = patterns.find(p => p.id === currentEditingPatternId);

            if (pattern) {

                pattern.template = newTemplate;

                document.getElementById(`template-${currentEditingPatternId}`).value = newTemplate;

                updateFinalPreview();

            }

            closeModal();

        }



        function closeModal() {

            document.getElementById('modal').classList.remove('active');

            currentEditingPatternId = null;

        }



        function updateFinalPreview() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern || !task) {

                document.getElementById('finalPreview').textContent = 'Select a pattern and enter your task to see the final prompt...';

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);

            document.getElementById('finalPreview').textContent = finalPrompt;



            updateExports(finalPrompt, pattern);

            updateStats();

        }



        function updateStats() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern) {

                document.getElementById('charCount').textContent = task.length;

                document.getElementById('wordCount').textContent = task.split(/\s+/).filter(w => w).length;

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);



            document.getElementById('charCount').textContent = finalPrompt.length;

            document.getElementById('wordCount').textContent = finalPrompt.split(/\s+/).filter(w => w).length;

        }



        function updateExports(prompt, pattern) {

            // JSON Export

            const jsonData = {

                name: pattern.name,

                type: pattern.type,

                prompt: prompt,

                tradeoffs: {

                    clarity: pattern.clarity,

                    flexibility: pattern.flexibility,

                    creativity: pattern.creativity

                },

                timestamp: new Date().toISOString()

            };

            document.getElementById('jsonExport').textContent = JSON.stringify(jsonData, null, 2);



            // Markdown Export

            const markdown = `# ${pattern.name}



**Type:** ${pattern.type}



## Prompt

\`\`\`

${prompt}

\`\`\`



## Tradeoff Analysis

- **Clarity:** ${pattern.clarity}%

- **Flexibility:** ${pattern.flexibility}%

- **Creativity:** ${pattern.creativity}%



---

*Generated: ${new Date().toLocaleString()}*`;

            document.getElementById('markdownExport').textContent = markdown;

        }



        function copyToClipboard(selector) {

            const text = document.querySelector(selector).textContent;

            navigator.clipboard.writeText(text).then(() => {

                alert('Copied to clipboard!');

            });

        }



        function downloadPromptCard() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern || !task) {

                alert('Please select a pattern and enter a task');

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);



            const content = `Prompt Framing Workshop - Exported Card

=====================================



Pattern: ${pattern.name}

Type: ${pattern.type}

Date: ${new Date().toLocaleString()}



FINAL PROMPT:

---

${finalPrompt}

---



TRADEOFF ANALYSIS:

- Clarity: ${pattern.clarity}%

- Flexibility: ${pattern.flexibility}%

- Creativity: ${pattern.creativity}%



Original Task:

${task}`;



            const blob = new Blob([content], { type: 'text/plain' });

            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');

            a.href = url;

            a.download = `prompt-card-${pattern.name.replace(/\s+/g, '-').toLowerCase()}-${Date.now()}.txt`;

            a.click();

            URL.revokeObjectURL(url);

        }



        function saveToLocalStorage() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern) {

                alert('Please select a pattern');

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);



            const data = {

                patternId: selectedPattern,

                patternName: pattern.name,

                template: pattern.template,

                task: task,

                finalPrompt: finalPrompt,

                tradeoffs: {

                    clarity: pattern.clarity,

                    flexibility: pattern.flexibility,

                    creativity: pattern.creativity

                },

                savedAt: new Date().toISOString()

            };



            localStorage.setItem('promptCard', JSON.stringify(data));

            alert('Saved to browser storage!');

        }



        function loadFromLocalStorage() {

            const stored = localStorage.getItem('promptCard');

            if (!stored) {

                alert('No saved prompt card found');

                return;

            }



            const data = JSON.parse(stored);

            document.getElementById('userTask').value = data.task;

            selectPattern(data.patternId);

            alert(`Loaded: "${data.patternName}" from ${new Date(data.savedAt).toLocaleString()}`);

        }



        function clearAll() {

            if (confirm('Are you sure? This will clear all inputs.')) {

                document.getElementById('userTask').value = '';

                selectedPattern = null;

                document.querySelectorAll('.pattern-card').forEach(card => {

                    card.style.opacity = '1';

                });

                document.getElementById('finalPreview').textContent = 'Select a pattern and enter your task to see the final prompt...';

                updateStats();

            }

        }



        function setupEventListeners() {

            document.getElementById('userTask').addEventListener('input', updateFinalPreview);



            // Tab switching

            document.querySelectorAll('.tab').forEach(tab => {

                tab.addEventListener('click', (e) => {

                    const tabName = e.target.dataset.tab;

                    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));

                    document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));

                    e.target.classList.add('active');

                    document.getElementById(tabName).classList.add('active');

                });

            });



            // Close modal on outside click

            document.getElementById('modal').addEventListener('click', (e) => {

                if (e.target.id === 'modal') {

                    closeModal();

                }

            });

        }



        // Initialize on page load

        window.addEventListener('DOMContentLoaded', init);

    </script>

</body>

</html>
