<body>

    <div class="container">

        <!-- Header -->

        <header id="header">

            <h1>🎯 Prompt Framing Workshop</h1>

            <p class="subtitle">Compare prompt patterns, adjust tradeoffs, and export your custom prompt card</p>

        </header>



        <!-- Task Input -->

        <div class="task-input-section" id="taskSection">

            <label for="userTask">Your Task or Goal</label>

            <textarea id="userTask" placeholder="Example: Write a compelling product description for a sustainable water bottle..."></textarea>

        </div>



        <!-- Pattern Cards -->

        <div class="patterns-grid" id="patternsGrid"></div>



        <!-- Export Section -->

        <div class="export-section" id="exportSection">

            <h2>📤 Export Your Custom Prompt Card</h2>



            <div class="stats" id="statsContainer"></div>



            <div class="tabs" id="tabsContainer"></div>



            <div id="view" class="tab-content active">

                <div class="preview-section">

                    <h3>Final Prompt Preview</h3>

                    <div class="prompt-preview" id="finalPreview">Select a pattern and enter your task to see the final prompt...</div>

                </div>

            </div>



            <div id="json" class="tab-content">

                <div class="json-export" id="jsonExport"></div>

                <button class="btn-primary copy-btn" id="copyJsonBtn">📋 Copy JSON</button>

            </div>



            <div id="markdown" class="tab-content">

                <div class="json-export" id="markdownExport"></div>

                <button class="btn-primary copy-btn" id="copyMarkdownBtn">📋 Copy Markdown</button>

            </div>



            <div class="actions" id="actionsContainer"></div>

        </div>

    </div>



    <!-- Modal for viewing full patterns -->

    <div class="modal" id="modal">

        <div class="modal-content">

            <h3 id="modalTitle">Edit Pattern</h3>

            <textarea id="modalTextarea"></textarea>

            <div class="modal-actions" id="modalActions"></div>

        </div>

    </div>



    <script>

        // Define prompt framing patterns

        const patterns = [

            {

                id: 1,

                name: "Direct & Clear",

                type: "Straightforward",

                template: "Task: {task}\n\nProvide a clear, concise response focused on the core requirement.",

                clarity: 95,

                flexibility: 60,

                creativity: 40,

                description: "Best for: Technical tasks, documentation, factual queries"

            },

            {

                id: 2,

                name: "Context-Rich",

                type: "Detailed",

                template: "Context: I need help with the following task.\n\nTask: {task}\n\nBackground: Consider relevant context, constraints, and best practices. Provide nuanced output that accounts for multiple perspectives.",

                clarity: 75,

                flexibility: 85,

                creativity: 70,

                description: "Best for: Complex problems, strategy, analysis"

            },

            {

                id: 3,

                name: "Persona & Role",

                type: "Roleplay",

                template: "You are an expert consultant specializing in this domain.\n\nClient request: {task}\n\nApproach this with your professional expertise, considering industry standards and innovative solutions.",

                clarity: 70,

                flexibility: 75,

                creativity: 90,

                description: "Best for: Creative work, specialized advice, brainstorming"

            }

        ];



        let selectedPattern = null;

        let currentEditingPatternId = null;



        // Initialize the workshop

        function init() {

            renderPatterns();

            renderStats();

            renderTabs();

            renderActions();

            renderModalActions();

            setupEventListeners();

        }



        function renderPatterns() {

            const grid = document.getElementById('patternsGrid');

            grid.textContent = '';



            patterns.forEach(pattern => {

                const card = document.createElement('div');

                card.className = `pattern-card pattern-${pattern.id}`;



                // Pattern type badge

                const typeBadge = document.createElement('span');

                typeBadge.className = 'pattern-type';

                typeBadge.textContent = pattern.type;



                // Pattern name

                const nameEl = document.createElement('h3');

                nameEl.textContent = pattern.name;



                // Pattern description

                const descEl = document.createElement('p');

                descEl.className = 'pattern-description';

                descEl.textContent = pattern.description;



                // Template textarea

                const textarea = document.createElement('textarea');

                textarea.id = `template-${pattern.id}`;

                textarea.setAttribute('data-pattern-id', pattern.id);

                textarea.textContent = pattern.template;



                // Clarity meter

                const clarityMeter = createMeterElement('Clarity', pattern.clarity, `clarity-${pattern.id}`);



                // Flexibility meter

                const flexibilityMeter = createMeterElement('Flexibility', pattern.flexibility, `flexibility-${pattern.id}`);



                // Creativity meter

                const creativityMeter = createMeterElement('Creativity', pattern.creativity, `creativity-${pattern.id}`);



                // Action buttons container

                const actionsDiv = document.createElement('div');

                actionsDiv.className = 'actions';



                const useBtn = document.createElement('button');

                useBtn.className = 'btn-primary';

                useBtn.textContent = 'Use Pattern';

                useBtn.setAttribute('data-pattern-id', pattern.id);



                const editBtn = document.createElement('button');

                editBtn.className = 'btn-secondary';

                editBtn.textContent = 'Edit';

                editBtn.setAttribute('data-pattern-id', pattern.id);



                actionsDiv.appendChild(useBtn);

                actionsDiv.appendChild(editBtn);



                // Assemble card

                card.appendChild(typeBadge);

                card.appendChild(nameEl);

                card.appendChild(descEl);

                card.appendChild(textarea);

                card.appendChild(clarityMeter);

                card.appendChild(flexibilityMeter);

                card.appendChild(creativityMeter);

                card.appendChild(actionsDiv);



                grid.appendChild(card);

            });

        }



        function createMeterElement(label, value, id) {

            const meterDiv = document.createElement('div');

            meterDiv.className = 'tradeoff-meter';



            const labelDiv = document.createElement('div');

            labelDiv.className = 'meter-label';



            const labelText = document.createElement('span');

            labelText.textContent = label;



            const labelValue = document.createElement('span');

            labelValue.id = id;

            labelValue.textContent = `${value}%`;



            labelDiv.appendChild(labelText);

            labelDiv.appendChild(labelValue);



            const barDiv = document.createElement('div');

            barDiv.className = 'meter-bar';



            const fillDiv = document.createElement('div');

            fillDiv.className = 'meter-fill';

            fillDiv.style.width = `${value}%`;



            barDiv.appendChild(fillDiv);



            meterDiv.appendChild(labelDiv);

            meterDiv.appendChild(barDiv);



            return meterDiv;

        }



        function renderStats() {

            const statsContainer = document.getElementById('statsContainer');

            statsContainer.textContent = '';



            // Character count stat

            const charStatBox = document.createElement('div');

            charStatBox.className = 'stat-box';



            const charValue = document.createElement('div');

            charValue.className = 'stat-value';

            charValue.id = 'charCount';

            charValue.textContent = '0';



            const charLabel = document.createElement('div');

            charLabel.className = 'stat-label';

            charLabel.textContent = 'Characters';



            charStatBox.appendChild(charValue);

            charStatBox.appendChild(charLabel);



            // Word count stat

            const wordStatBox = document.createElement('div');

            wordStatBox.className = 'stat-box';



            const wordValue = document.createElement('div');

            wordValue.className = 'stat-value';

            wordValue.id = 'wordCount';

            wordValue.textContent = '0';



            const wordLabel = document.createElement('div');

            wordLabel.className = 'stat-label';

            wordLabel.textContent = 'Words';



            wordStatBox.appendChild(wordValue);

            wordStatBox.appendChild(wordLabel);



            statsContainer.appendChild(charStatBox);

            statsContainer.appendChild(wordStatBox);

        }



        function renderTabs() {

            const tabsContainer = document.getElementById('tabsContainer');

            tabsContainer.textContent = '';



            const tabs = ['view', 'json', 'markdown'];

            const labels = ['View', 'JSON', 'Markdown'];



            tabs.forEach((tab, index) => {

                const tabBtn = document.createElement('button');

                tabBtn.className = 'tab';

                if (index === 0) tabBtn.classList.add('active');

                tabBtn.setAttribute('data-tab', tab);

                tabBtn.textContent = labels[index];



                tabsContainer.appendChild(tabBtn);

            });

        }



        function renderActions() {

            const actionsContainer = document.getElementById('actionsContainer');

            actionsContainer.textContent = '';

            actionsContainer.style.marginTop = '20px';



            const downloadBtn = document.createElement('button');

            downloadBtn.className = 'btn-success';

            downloadBtn.id = 'downloadBtn';

            downloadBtn.textContent = '⬇️ Download as Text';



            const saveBtn = document.createElement('button');

            saveBtn.className = 'btn-secondary';

            saveBtn.id = 'saveBtn';

            saveBtn.textContent = '💾 Save to Browser';



            const loadBtn = document.createElement('button');

            loadBtn.className = 'btn-secondary';

            loadBtn.id = 'loadBtn';

            loadBtn.textContent = '📂 Load from Browser';



            const clearBtn = document.createElement('button');

            clearBtn.className = 'btn-danger';

            clearBtn.id = 'clearBtn';

            clearBtn.textContent = '🗑️ Clear All';



            actionsContainer.appendChild(downloadBtn);

            actionsContainer.appendChild(saveBtn);

            actionsContainer.appendChild(loadBtn);

            actionsContainer.appendChild(clearBtn);

        }



        function renderModalActions() {

            const modalActions = document.getElementById('modalActions');

            modalActions.textContent = '';



            const saveBtn = document.createElement('button');

            saveBtn.className = 'btn-primary';

            saveBtn.id = 'modalSaveBtn';

            saveBtn.textContent = 'Save';



            const cancelBtn = document.createElement('button');

            cancelBtn.className = 'btn-secondary';

            cancelBtn.id = 'modalCancelBtn';

            cancelBtn.textContent = 'Cancel';



            modalActions.appendChild(saveBtn);

            modalActions.appendChild(cancelBtn);

        }



        function selectPattern(patternId) {

            selectedPattern = patternId;

            updateFinalPreview();

            document.querySelectorAll('.pattern-card').forEach(card => {

                card.style.opacity = '0.5';

            });

            document.querySelector(`.pattern-${patternId}`).style.opacity = '1';

        }



        function editPattern(patternId) {

            currentEditingPatternId = patternId;

            const textarea = document.getElementById(`template-${patternId}`);

            document.getElementById('modalTextarea').value = textarea.value;

            document.getElementById('modal').classList.add('active');

        }



        function saveModalEdit() {

            const newTemplate = document.getElementById('modalTextarea').value;

            const pattern = patterns.find(p => p.id === currentEditingPatternId);

            if (pattern) {

                pattern.template = newTemplate;

                document.getElementById(`template-${currentEditingPatternId}`).value = newTemplate;

                updateFinalPreview();

            }

            closeModal();

        }



        function closeModal() {

            document.getElementById('modal').classList.remove('active');

            currentEditingPatternId = null;

        }



        function updateFinalPreview() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern || !task) {

                document.getElementById('finalPreview').textContent = 'Select a pattern and enter your task to see the final prompt...';

                updateStats();

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);

            document.getElementById('finalPreview').textContent = finalPrompt;



            updateExports(finalPrompt, pattern);

            updateStats();

        }



        function updateStats() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern) {

                document.getElementById('charCount').textContent = task.length;

                document.getElementById('wordCount').textContent = task.split(/\s+/).filter(w => w).length;

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);



            document.getElementById('charCount').textContent = finalPrompt.length;

            document.getElementById('wordCount').textContent = finalPrompt.split(/\s+/).filter(w => w).length;

        }



        function updateExports(prompt, pattern) {

            // JSON Export

            const jsonData = {

                name: pattern.name,

                type: pattern.type,

                prompt: prompt,

                tradeoffs: {

                    clarity: pattern.clarity,

                    flexibility: pattern.flexibility,

                    creativity: pattern.creativity

                },

                timestamp: new Date().toISOString()

            };

            document.getElementById('jsonExport').textContent = JSON.stringify(jsonData, null, 2);



            // Markdown Export

            const timestamp = new Date().toLocaleString();

            const markdown = `# ${pattern.name}



**Type:** ${pattern.type}



## Prompt

\`\`\`

${prompt}

\`\`\`



## Tradeoff Analysis

- **Clarity:** ${pattern.clarity}%

- **Flexibility:** ${pattern.flexibility}%

- **Creativity:** ${pattern.creativity}%



---

*Generated: ${timestamp}*`;

            document.getElementById('markdownExport').textContent = markdown;

        }



        function copyToClipboard(elementId) {

            const text = document.getElementById(elementId).textContent;

            navigator.clipboard.writeText(text).then(() => {

                alert('Copied to clipboard!');

            }).catch(() => {

                alert('Failed to copy to clipboard');

            });

        }



        function downloadPromptCard() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern || !task) {

                alert('Please select a pattern and enter a task');

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);

            const timestamp = new Date().toLocaleString();



            const content = `Prompt Framing Workshop - Exported Card

=====================================



Pattern: ${pattern.name}

Type: ${pattern.type}

Date: ${timestamp}



FINAL PROMPT:

---

${finalPrompt}

---



TRADEOFF ANALYSIS:

- Clarity: ${pattern.clarity}%

- Flexibility: ${pattern.flexibility}%

- Creativity: ${pattern.creativity}%



Original Task:

${task}`;



            const blob = new Blob([content], { type: 'text/plain' });

            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');

            a.href = url;

            a.download = `prompt-card-${pattern.name.replace(/\s+/g, '-').toLowerCase()}-${Date.now()}.txt`;

            document.body.appendChild(a);

            a.click();

            document.body.removeChild(a);

            URL.revokeObjectURL(url);

        }



        function saveToLocalStorage() {

            const task = document.getElementById('userTask').value;

            if (!selectedPattern) {

                alert('Please select a pattern');

                return;

            }



            const pattern = patterns.find(p => p.id === selectedPattern);

            const finalPrompt = pattern.template.replace('{task}', task);



            const data = {

                patternId: selectedPattern,

                patternName: pattern.name,

                template: pattern.template,

                task: task,

                finalPrompt: finalPrompt,

                tradeoffs: {

                    clarity: pattern.clarity,

                    flexibility: pattern.flexibility,

                    creativity: pattern.creativity

                },

                savedAt: new Date().toISOString()

            };



            localStorage.setItem('promptCard', JSON.stringify(data));

            alert('Saved to browser storage!');

        }



        function loadFromLocalStorage() {

            const stored = localStorage.getItem('promptCard');

            if (!stored) {

                alert('No saved prompt card found');

                return;

            }



            const data = JSON.parse(stored);

            document.getElementById('userTask').value = data.task;

            selectPattern(data.patternId);

            const savedDate = new Date(data.savedAt).toLocaleString();

            alert(`Loaded: "${data.patternName}" from ${savedDate}`);

        }



        function clearAll() {

            if (confirm('Are you sure? This will clear all inputs.')) {

                document.getElementById('userTask').value = '';

                selectedPattern = null;

                document.querySelectorAll('.pattern-card').forEach(card => {

                    card.style.opacity = '1';

                });

                document.getElementById('finalPreview').textContent = 'Select a pattern and enter your task to see the final prompt...';

                updateStats();

            }

        }



        function setupEventListeners() {

            // Task input

            document.getElementById('userTask').addEventListener('input', updateFinalPreview);



            // Pattern card buttons

            document.getElementById('patternsGrid').addEventListener('click', (e) => {

                if (e.target.classList.contains('btn-primary')) {

                    const patternId = parseInt(e.target.getAttribute('data-pattern-id'));

                    selectPattern(patternId);

                }

                if (e.target.classList.contains('btn-secondary') && e.target.textContent === 'Edit') {

                    const patternId = parseInt(e.target.getAttribute('data-pattern-id'));

                    editPattern(patternId);

                }

            });



            // Tab switching

            document.getElementById('tabsContainer').addEventListener('click', (e) => {

                if (e.target.classList.contains('tab')) {

                    const tabName = e.target.getAttribute('data-tab');

                    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));

                    document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));

                    e.target.classList.add('active');

                    document.getElementById(tabName).classList.add('active');

                }

            });



            // Copy buttons

            document.getElementById('copyJsonBtn').addEventListener('click', () => {

                copyToClipboard('jsonExport');

            });



            document.getElementById('copyMarkdownBtn').addEventListener('click', () => {

                copyToClipboard('markdownExport');

            });



            // Action buttons

            document.getElementById('downloadBtn').addEventListener('click', downloadPromptCard);

            document.getElementById('saveBtn').addEventListener('click', saveToLocalStorage);

            document.getElementById('loadBtn').addEventListener('click', loadFromLocalStorage);

            document.getElementById('clearBtn').addEventListener('click', clearAll);



            // Modal buttons

            document.getElementById('modalSaveBtn').addEventListener('click', saveModalEdit);

            document.getElementById('modalCancelBtn').addEventListener('click', closeModal);



            // Close modal on outside click

            document.getElementById('modal').addEventListener('click', (e) => {

                if (e.target.id === 'modal') {

                    closeModal();

                }

            });

        }



        // Initialize on page load

        window.addEventListener('DOMContentLoaded', init);

    </script>

